```js
const subscriptions = new Set();

function ensureUri(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    const err = new Error('uri must be a non-empty string');
    err.code = -32602;
    throw err;
  }
}

export async function subscribeResource(uri) {
  ensureUri(uri);
  if (subscriptions.has(uri)) {
    const err = new Error('already subscribed: ' + uri);
    err.code = -32602;
    throw err;
  }
  subscriptions.add(uri);
  return { subscribed: true, uri };
}

export async function unsubscribeResource(uri) {
  ensureUri(uri);
  if (!subscriptions.has(uri)) {
    const err = new Error('not subscribed: ' + uri);
    err.code = -32602;
    throw err;
  }
  subscriptions.delete(uri);
  return { unsubscribed: true, uri };
}

export async function listTools() {
  return [
    {
      name: 'subscribeResource',
      description: 'Subscribe to a resource by URI. Requires a non-empty URI. Rejects duplicate subscriptions.',
      inputSchema: {
        type: 'object',
        properties: { uri: { type: 'string', description: 'The non-empty resource URI to subscribe to.' } },
        required: ['uri'],
        additionalProperties: false,
      },
    },
    {
      name: 'unsubscribeResource',
      description: 'Unsubscribe from a resource by URI. Rejects missing subscriptions.',
      inputSchema: {
        type: 'object',
        properties: { uri: { type: 'string', description: 'The resource URI to unsubscribe from.' } },
        required: ['uri'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'subscribeResource':
      return await subscribeResource(args.uri);
    case 'unsubscribeResource':
      return await unsubscribeResource(args.uri);
    default: {
      const err = new Error('unknown tool: ' + name);
      err.code = -32601;
      throw err;
    }
  }
}
```

